    static ActivationResult activateProduction()throws Exception{
        verifySources();FrozenCompositionKeySpecificChannelCandidate.verifyIdentity(FrozenCompositionKeySpecificChannelCandidate.VERSION,FrozenCompositionKeySpecificChannelCandidate.HASH);FrozenCompositionProductionCandidate.verifyExact();
        Prepared p=prepare();List<Map<String,String>>frozenRows=CompositionDecisionTimeProvenanceCapture.read(OUT.resolve("phase-13d-final-holdout-schedule.csv"));
        int scheduleMismatch=frozenRows.size()==p.schedule().size()?0:1;
        Map<String,CompositionFreshHoldoutCandidateGameplayAudit.Lineup>lineups=p.pool().stream().collect(Collectors.toMap(CompositionFreshHoldoutCandidateGameplayAudit.Lineup::id,Function.identity()));
        int parityMismatch=0,replayMismatch=0,rollbackMismatch=0;
        for(var row:p.schedule().subList(0,PRODUCTION_REPLAYS)){
            MatchChampionAssignments a=CompositionAuditOnlySemanticsRuntime.assignments(lineups.get(row.blueLineupId()),lineups.get(row.redLineupId()));
            var validated=CompositionAuditOnlySemanticsRuntime.simulate(simulator(TeamCompositionGameplayMode.SHADOW,row.caseIndex(),true),row,a);
            var production=CompositionAuditOnlySemanticsRuntime.simulate(productionSimulator(),row,a);
            var productionReplay=CompositionAuditOnlySemanticsRuntime.simulate(productionSimulator(),row,a);
            var off=CompositionAuditOnlySemanticsRuntime.simulate(simulator(TeamCompositionGameplayMode.OFF,-1,false),row,a);
            var offReplay=CompositionAuditOnlySemanticsRuntime.simulate(simulator(TeamCompositionGameplayMode.OFF,-1,false),row,a);
            if(!exact(production,validated))parityMismatch++;
            if(!exact(production,productionReplay))replayMismatch++;
            if(!exact(off,offReplay))rollbackMismatch++;
        }
        int integrity=scheduleMismatch+parityMismatch+replayMismatch+rollbackMismatch;
        String verdict=integrity==0?"PHASE_13D_TEAM_COMPOSITION_COMPLETE":"BLOCKED_BY_PHASE_13D_PRODUCTION_ACTIVATION";
        ActivationResult result=new ActivationResult(parityMismatch,replayMismatch,rollbackMismatch,integrity,verdict);
        writeActivationClosure(result);return result;
    }

