    static Prepared prepare()throws Exception{
        var canonical=CompositionFreshHoldoutCandidateGameplayAudit.readCanonical();List<Map<String,String>>priorRows=CompositionDecisionTimeProvenanceCapture.read(PRIOR);Set<String>priorLineups=new HashSet<>(),priorUnordered=new HashSet<>(),priorOrdered=new HashSet<>();Set<Long>priorSeeds=new HashSet<>();for(var r:priorRows){String b=r.get("blueLineupId"),d=r.get("redLineupId");priorLineups.add(b);priorLineups.add(d);priorUnordered.add(norm(b,d));priorOrdered.add(b+"|"+d);priorSeeds.add(Long.parseLong(r.get("seed")));}
        List<CompositionFreshHoldoutCandidateGameplayAudit.Lineup>pool=canonical.stream().filter(x->!priorLineups.contains(x.id())).sorted(Comparator.comparing(x->sha256(FrozenCompositionProductionCandidate.HASH+"|lineup|"+x.id()))).limit(LINEUPS).toList();if(pool.size()!=LINEUPS)throw new IllegalStateException("insufficient fresh lineups");
        List<Edge>all=new ArrayList<>();for(int i=0;i<pool.size();i++)for(int j=i+1;j<pool.size();j++)if(disjoint(pool.get(i),pool.get(j))){String id=norm(pool.get(i).id(),pool.get(j).id());if(!priorUnordered.contains(id))all.add(new Edge(i,j,pool.get(i),pool.get(j),id));}all.sort(Comparator.comparing(x->sha256(FrozenCompositionProductionCandidate.HASH+"|pair|"+x.id())));
        List<Edge>edges=balanced(all,pool.size());Set<Long>used=new HashSet<>();List<CompositionAuditOnlySemanticsRuntime.ScheduleCase>schedule=new ArrayList<>();for(int g=0;g<edges.size();g++){Edge e=edges.get(g);long seed=seed(e.id(),priorSeeds,used);String ph=sha256(e.id());schedule.add(new CompositionAuditOnlySemanticsRuntime.ScheduleCase(g*2,g*2,g,seed,0,e.a().id(),e.b().id(),ph));schedule.add(new CompositionAuditOnlySemanticsRuntime.ScheduleCase(g*2+1,g*2+1,g,seed,1,e.b().id(),e.a().id(),ph));}
        int lo=(int)pool.stream().filter(x->priorLineups.contains(x.id())).count(),uo=(int)edges.stream().filter(x->priorUnordered.contains(x.id())).count(),oo=(int)schedule.stream().filter(x->priorOrdered.contains(x.blueLineupId()+"|"+x.redLineupId())).count(),so=(int)used.stream().filter(priorSeeds::contains).count();int missing=(int)edges.stream().filter(e->schedule.stream().filter(x->x.pairHash().equals(sha256(e.id()))).count()!=2).count();return new Prepared(pool,edges,List.copyOf(schedule),lo,uo,oo,so,used.size()==PAIRS?0:1,missing,hashSchedule(schedule));
    }
    static List<Edge>balanced(List<Edge>all,int n){for(int attempt=0;attempt<100;attempt++){int[]remaining=new int[n];Arrays.fill(remaining,7);List<Integer>rank=new ArrayList<>();for(int i=0;i<n;i++)rank.add(i);int q=attempt;rank.sort(Comparator.comparing(i->sha256(q+"|degree|"+i)));for(int i=0;i<80;i++)remaining[rank.get(i)]=8;Set<String>used=new HashSet<>();List<Edge>out=new ArrayList<>();while(out.size()<PAIRS){Edge best=null;String key=null;int score=-1;for(Edge e:all)if(remaining[e.i()]>0&&remaining[e.j()]>0&&!used.contains(e.id())){int s=remaining[e.i()]+remaining[e.j()];String k=sha256(attempt+"|"+e.id());if(s>score||s==score&&(key==null||k.compareTo(key)<0)){best=e;key=k;score=s;}}if(best==null)break;out.add(best);used.add(best.id());remaining[best.i()]--;remaining[best.j()]--;}if(out.size()==PAIRS&&Arrays.stream(remaining).allMatch(x->x==0))return List.copyOf(out);}throw new IllegalStateException("unable to build fresh balanced pair graph");}

