    static boolean exact(MatchSimulator.SimulationResult a,MatchSimulator.SimulationResult b){return a.winnerSide()==b.winnerSide()&&a.timeline().getDurationSeconds()==b.timeline().getDurationSeconds()&&CompositionAuditOnlySemanticsRuntime.hash(a.timeline().getEvents()).equals(CompositionAuditOnlySemanticsRuntime.hash(b.timeline().getEvents()))&&CompositionAuditOnlySemanticsRuntime.hash(a.timeline().getSnapshots()).equals(CompositionAuditOnlySemanticsRuntime.hash(b.timeline().getSnapshots()))&&CompositionAuditOnlySemanticsRuntime.hash(a.randomTrace()).equals(CompositionAuditOnlySemanticsRuntime.hash(b.randomTrace()));}

    static Map<TeamCompositionContext,LocalMetric>localMetrics(List<CompositionWinnerDecisionProvenance>all){Map<TeamCompositionContext,LocalMetric>out=new EnumMap<>(TeamCompositionContext.class);for(var c:CONTEXTS){List<CompositionWinnerDecisionProvenance>apps=all.stream().filter(x->x.context()==c).toList(),flips=apps.stream().filter(x->x.baselineCounterfactualWinner()!=x.runtimeWinner()).toList();long near=0,mid=0,far=0,direction=0,decision=0,same=0,opposing=0,gold=0,progression=0,power=0,matchup=0;var bands=CompositionDecisionTimeProvenanceCapture.BANDS.get(c);List<Double>ratios=new ArrayList<>();for(var p:apps){if(p.compositionModifier()!=0&&Math.signum(p.compositionModifier())!=Math.signum(p.compositionEdge()))direction++;TeamSide expected=p.randomSample()>=.5-p.candidateScore()/56?TeamSide.BLUE:TeamSide.RED;if(expected!=p.runtimeWinner())decision++;}for(var p:flips){double margin=Math.abs(p.randomSample()-(.5-p.baselineScore()/56));String band=bands.band(margin);if(band.equals("NEAR"))near++;else if(band.equals("MID"))mid++;else far++;String base=relation(p.baselineScore(),p.compositionEdge());if(base.equals("SAME_DIRECTION"))same++;if(base.equals("OPPOSING_DIRECTION"))opposing++;if(relation(p.blueGold()-p.redGold(),p.compositionEdge()).equals("OPPOSING_DIRECTION"))gold++;if(relation(p.progressionContribution(),p.compositionEdge()).equals("OPPOSING_DIRECTION"))progression++;if(relation(p.championPowerContribution(),p.compositionEdge()).equals("OPPOSING_DIRECTION"))power++;if(relation(p.matchupContribution(),p.compositionEdge()).equals("OPPOSING_DIRECTION"))matchup++;if(Math.abs(p.baselineScore())>=1e-9)ratios.add(Math.abs(p.compositionModifier()/p.baselineScore()));}Collections.sort(ratios);boolean safe=direction==0&&decision==0&&far==0&&(flips.isEmpty()||(double)near/flips.size()>=.95);out.put(c,new LocalMetric(apps.size(),flips.size(),rate(flips.size(),apps.size()),near,mid,far,direction,decision,same,opposing,gold,progression,power,matchup,q(ratios,.5),q(ratios,.9),q(ratios,.95),safe));}return Map.copyOf(out);}
    static Controls controls(List<CompositionWinnerDecisionProvenance>all){Map<TeamCompositionContext,List<CompositionWinnerDecisionProvenance>>m=new EnumMap<>(TeamCompositionContext.class);for(var c:CONTEXTS){int max=c==TeamCompositionContext.TEAMFIGHT?150:c==TeamCompositionContext.SIEGE?75:100;m.put(c,all.stream().filter(x->x.context()==c&&x.baselineCounterfactualWinner()==x.runtimeWinner()).sorted(Comparator.comparing(x->sha256(x.caseIndex()+"|"+x.attemptId()+"|"+x.context()))).limit(max).toList());}return new Controls(Map.copyOf(m));}
    static Macro macro(List<CompositionAuditOnlySemanticsRuntime.PairedGame>g,List<CompositionWinnerDecisionProvenance>p){long pub=g.stream().filter(x->!x.offTimelineHash().equals(x.auditTimelineHash())).count(),win=g.stream().filter(x->x.offWinner()!=x.auditWinner()).count(),obj=g.stream().filter(x->!x.offObjectiveSignature().equals(x.auditObjectiveSignature())).count(),str=g.stream().filter(x->!x.offStructureSignature().equals(x.auditStructureSignature())).count();Set<Integer>causes=p.stream().filter(x->x.baselineCounterfactualWinner()!=x.runtimeWinner()).map(CompositionWinnerDecisionProvenance::caseIndex).collect(Collectors.toSet());long gaps=g.stream().filter(x->!x.offTimelineHash().equals(x.auditTimelineHash())&&!causes.contains(x.caseIndex())).count();double offBlue=rate(g.stream().filter(x->x.offWinner()==TeamSide.BLUE).count(),g.size()),candBlue=rate(g.stream().filter(x->x.auditWinner()==TeamSide.BLUE).count(),g.size());List<Integer>od=g.stream().map(CompositionAuditOnlySemanticsRuntime.PairedGame::offDuration).sorted().toList(),cd=g.stream().map(CompositionAuditOnlySemanticsRuntime.PairedGame::auditDuration).sorted().toList();double om=g.stream().mapToInt(CompositionAuditOnlySemanticsRuntime.PairedGame::offDuration).average().orElse(0),cm=g.stream().mapToInt(CompositionAuditOnlySemanticsRuntime.PairedGame::auditDuration).average().orElse(0);return new Macro(pub,rate(pub,g.size()),gaps,win,rate(win,g.size()),obj,rate(obj,g.size()),str,rate(str,g.size()),offBlue,candBlue,Math.abs(candBlue-offBlue),cm-om,qint(cd,.95)-qint(od,.95));}

