    static void verifySources()throws Exception{for(var e:SOURCES.entrySet())if(!e.getValue().equals(sha256(e.getKey())))throw new IllegalStateException("source hash mismatch "+e.getKey());}
    static void csv(String name,List<List<String>>rows)throws IOException{StringBuilder b=new StringBuilder();for(var r:rows){for(int i=0;i<r.size();i++){if(i>0)b.append(',');String v=r.get(i);if(v.contains(",")||v.contains("\"")||v.contains("\n"))b.append('"').append(v.replace("\"","\"\"")).append('"');else b.append(v);}b.append('\n');}Files.writeString(OUT.resolve(name),b,StandardCharsets.UTF_8);}
    static String sha256(Path p)throws Exception{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p)));}static String sha256(String s){try{return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}static String norm(String a,String b){return a.compareTo(b)<0?a+"|"+b:b+"|"+a;}static boolean disjoint(CompositionFreshHoldoutCandidateGameplayAudit.Lineup a,CompositionFreshHoldoutCandidateGameplayAudit.Lineup b){return Collections.disjoint(a.champions().values(),b.champions().values());}static long seed(String id,Set<Long>prior,Set<Long>used){int n=0;while(true){byte[]b;try{b=MessageDigest.getInstance("SHA-256").digest((FrozenCompositionProductionCandidate.HASH+"|seed|"+id+"|"+n++).getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}long v=java.nio.ByteBuffer.wrap(b).getLong();if(!prior.contains(v)&&used.add(v))return v;}}static String hashSchedule(List<CompositionAuditOnlySemanticsRuntime.ScheduleCase>s){return sha256(s.stream().map(x->x.caseIndex()+"|"+x.seed()+"|"+x.blueLineupId()+"|"+x.redLineupId()).collect(Collectors.joining("\n")));}static String relation(double a,double edge){if(Math.abs(a)<1e-12||Math.abs(edge)<1e-12)return"NEUTRAL";return Math.signum(a)==Math.signum(edge)?"SAME_DIRECTION":"OPPOSING_DIRECTION";}static double rate(long a,long b){return b==0?0:(double)a/b;}static double q(List<Double>x,double p){if(x.isEmpty())return 0;return x.get((int)Math.floor(p*(x.size()-1)));}static double qint(List<Integer>x,double p){return x.isEmpty()?0:x.get((int)Math.floor(p*(x.size()-1)));}static String s(long x){return Long.toString(x);}static String f(double x){return String.format(Locale.ROOT,"%.12f",x);}

